func TestSpecPinsS8Registered(t *testing.T) {
	t.Parallel()
	seen := map[string]bool{}
	for _, p := range specPinRegistry {
		if strings.HasPrefix(p.Row, "T8.") {
			seen[p.Row] = true
		}
	}
	if len(seen) != 182 {
		t.Fatalf("the section 8 registry names %d non-informative rows; want 182 (of 263 total T8.* rows)", len(seen))
	}
}

func TestSpecPinsS8Plant(t *testing.T) {
	t.Parallel()
	root := repoRoot(t)
	base := os.DirFS(root)
	spec, err := fs.ReadFile(base, "docs/SPEC-TABLES.md")
	if err != nil {
		t.Fatal(err)
	}
	const heading = "### 8.2 The type view: every type, on the side\n"
	if !strings.Contains(string(spec), heading) {
		t.Fatalf("the spec no longer carries %q; the plant needs a live pinned section", heading)
	}
	const rule = "A view must not invent a type that the declaration did not write.\n"
	planted := strings.Replace(string(spec), heading, heading+"\n"+rule, 1)
	fsys := overlayFS{FS: base, over: map[string][]byte{"docs/SPEC-TABLES.md": []byte(planted)}}
	_, got := checkSpecPins(specPinsInput{fsys: fsys, spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
	all := strings.Join(got, "\n")
	if !strings.Contains(all, `normative sentence without a row id (section "8.2 The type view: every type, on the side")`) {
		t.Fatalf("planted an unmarked rule in section 8.2; the guard stayed green:\n%s", all)
	}
}

